from copy import deepcopy
import json
import sys
import xml.etree.ElementTree as ET

OUT = Path(__file__).resolve().parents[1]
BUILD = OUT / '.build'
ORIGINAL = BUILD / 'source-template'
SOURCE_STEM = 'CupMoscow2026-ОТП-НазваниеКоманды'
team = json.loads((OUT.parents[1] / 'project/team.json').read_text())
STEM = 'CupMoscow2026-ОТП-' + team['name']
NS = {'p': 'http://schemas.openxmlformats.org/presentationml/2006/main',
      'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
for key, value in NS.items(): ET.register_namespace(key, value)
Q = lambda n: '{' + NS[n.split(':')[0]] + '}' + n.split(':')[1]
EMU = 9525
INK, GREEN, LIME, MUTED = '14392F', '006B45', 'C7E943', '526A63'
PAPER, TINT, RULE, WHITE = 'FAFCFA', 'EDF5EE', 'D6E0D9', 'FFFFFF'

def node(parent, tag, **attrs):
    return ET.SubElement(parent, Q(tag), {k: str(v) for k, v in attrs.items()})

class Slide:
    def __init__(self, raw, number, title=None, source='', dark=False):
        self.root = ET.fromstring(raw)
        self.number, self.id = number, 1
        cs = self.root.find('p:cSld', NS)
        bg = cs.find('p:bg', NS)
        if bg is not None: cs.remove(bg)
        bg = ET.Element(Q('p:bg')); cs.insert(0, bg)
        prop = node(bg, 'p:bgPr'); self.fill(prop, INK if dark else PAPER)
        old = cs.find('p:spTree', NS)
        self.tree = ET.Element(Q('p:spTree'))
        self.tree.extend(deepcopy(list(old)[:2]))
        cs.remove(old); cs.append(self.tree)
        if not dark:
            self.text('ОТП МАНИЯ  /  ' + ('ИДЕЯ И ВНЕДРЕНИЕ' if number <= 8 else f'ПРИЛОЖЕНИЕ А{number-8}'), 64, 25, 1050, 24, 14, True, GREEN)
            self.text(title, 64, 65, 1152, 110, 38, True)
            self.box(64, 185, 1152, 2, RULE)
            self.text(source, 64, 690, 1090, 26, 12, False, MUTED)
            self.text(str(number), 1172, 690, 44, 24, 14, True, MUTED, 'r')

    @staticmethod
    def fill(parent, color):
        if color is None: node(parent, 'a:noFill')
        else: node(node(parent, 'a:solidFill'), 'a:srgbClr', val=color)

    def shape(self, x, y, w, h, fill=None, border=None, geom='rect', text=False):
        self.id += 1
        sp = node(self.tree, 'p:sp')
        nv = node(sp, 'p:nvSpPr'); node(nv, 'p:cNvPr', id=self.id, name=f'Slide{self.number} Shape{self.id}')
        node(nv, 'p:cNvSpPr', **({'txBox': '1'} if text else {})); node(nv, 'p:nvPr')
        pr = node(sp, 'p:spPr'); xf = node(pr, 'a:xfrm')
        node(xf, 'a:off', x=round(x*EMU), y=round(y*EMU))
        node(xf, 'a:ext', cx=round(w*EMU), cy=round(h*EMU))
        node(node(pr, 'a:prstGeom', prst=geom), 'a:avLst')
        self.fill(pr, fill); ln = node(pr, 'a:ln', w=9525 if border else 0); self.fill(ln, border)
        return sp

    def box(self, x, y, w, h, fill=TINT, border=None, geom='rect'):
        return self.shape(x, y, w, h, fill, border, geom)

    def text(self, text, x, y, w, h, size=25, bold=False, color=INK, align='l'):
        sp = self.shape(x, y, w, h, text=True)
        tx = node(sp, 'p:txBody')
        node(node(tx, 'a:bodyPr', wrap='square', lIns=0, tIns=0, rIns=0, bIns=0, anchor='t'), 'a:noAutofit')
        node(tx, 'a:lstStyle')
        for line in text.split('\n'):
            para = node(tx, 'a:p'); pp = node(para, 'a:pPr', algn=align)
            node(node(pp, 'a:lnSpc'), 'a:spcPct', val=110000)
            node(node(pp, 'a:spcAft'), 'a:spcPts', val=0)
            run = node(para, 'a:r'); rp = node(run, 'a:rPr', lang='ru-RU', sz=round(size*75), b=1 if bold else 0)
            self.fill(rp, color)
            for kind in ['latin', 'ea', 'cs']: node(rp, 'a:'+kind, typeface='Arial')
            t = node(run, 'a:t'); t.text = line
            node(para, 'a:endParaRPr', lang='ru-RU', sz=round(size*75))
        return sp

    def arrow(self, x, y): self.box(x, y, 18, 28, GREEN, geom='chevron')
    def xml(self): return ET.tostring(self.root, encoding='utf-8', xml_declaration=True)


with ZipFile(ORIGINAL / (SOURCE_STEM+'.pptx')) as z:
    data = {name:z.read(name) for name in z.namelist()}
notes, titles, links, external_links = {}, {}, {}, {}
RELNS='http://schemas.openxmlformats.org/package/2006/relationships'

def start(n,title,source):
    titles[n]=title.replace('\n',' ')
    return Slide(data[f'ppt/slides/slide{n}.xml'],n,title,source)

def finish(s,note):
    data[f'ppt/slides/slide{s.number}.xml']=s.xml(); notes[s.number]=note

def jump(s,label,page,x,y,w=400,size=15):
    sp=s.text(label,x,y,w,27,size,True,GREEN)
    rid=f'readDeckJump{len(links.get(s.number,[]))+1}'
    for rp in sp.findall('.//a:rPr',NS):node(rp,'a:hlinkClick',**{'{'+NS['r']+'}id':rid,'action':'ppaction://hlinksldjump'})
    links.setdefault(s.number,[]).append((rid,page))

def web_link(s,label,url,x,y,w=400,size=24):
    sp=s.text(label,x,y,w,32,size,True,GREEN)
    rid=f'readDeckWeb{len(external_links.get(s.number,[]))+1}'
    for rp in sp.findall('.//a:rPr',NS):
        rp.set('u','sng')
        node(rp,'a:hlinkClick',**{'{'+NS['r']+'}id':rid})
    external_links.setdefault(s.number,[]).append((rid,url))

def banner(s,text,y=605,size=24):
    s.box(64,y,1152,58,TINT)
    s.text(text,82,y+13,1116,43,size,True,GREEN)

def table(s,headers,rows,widths,top=231,heights=None,size=21):
    x=64
    for h,w in zip(headers,widths):
        s.box(x,top,w,50,INK);s.text(h,x+14,top+10,w-28,38,20,True,WHITE);x+=w
    y=top+50
    if heights is None:heights=[80]*len(rows)
    for i,(row,height) in enumerate(zip(rows,heights)):
        x=64
        for j,(val,w) in enumerate(zip(row,widths)):
            s.box(x,y,w,height,TINT if i%2==0 else WHITE,RULE)
            s.text(val,x+14,y+10,w-28,height-14,size,j==0,GREEN if j==0 else INK);x+=w
        y+=height
    return y

def card(s,x,y,w,h,label,body,size=22,dark=False):
    s.box(x,y,w,h,INK if dark else WHITE,None if dark else RULE)
    s.text(label,x+20,y+17,w-40,68,27,True,LIME if dark else GREEN)
    s.text(body,x+20,y+91,w-40,h-100,size,False,WHITE if dark else INK)

