# Speaker notes mirror the visible story; no necessary explanation is hidden there.
for n,note in notes.items():
    name=f'ppt/notesSlides/notesSlide{n}.xml'
    if name not in data:continue
    root=ET.fromstring(data[name])
    for sp in root.findall('.//p:sp',NS):
        ph=sp.find('p:nvSpPr/p:nvPr/p:ph',NS)
        if ph is not None and ph.get('type')=='body':
            tx=sp.find('p:txBody',NS)
            if tx is None:continue
            for para in list(tx):
                if para.tag==Q('a:p'):tx.remove(para)
            p=node(tx,'a:p');r=node(p,'a:r');node(r,'a:rPr',lang='ru-RU',sz=1200);node(r,'a:t').text=note
    data[name]=ET.tostring(root,encoding='utf-8',xml_declaration=True)
for n in sorted(set(links) | set(external_links)):
    name=f'ppt/slides/_rels/slide{n}.xml.rels'
    root=ET.fromstring(data[name]) if name in data else ET.Element('{'+RELNS+'}Relationships')
    for rid,page in links.get(n,[]):ET.SubElement(root,'{'+RELNS+'}Relationship',Id=rid,Type=NS['r']+'/slide',Target=f'slide{page}.xml')
    for rid,url in external_links.get(n,[]):ET.SubElement(root,'{'+RELNS+'}Relationship',Id=rid,Type=NS['r']+'/hyperlink',Target=url,TargetMode='External')
    data[name]=ET.tostring(root,encoding='utf-8',xml_declaration=True)
with ZipFile(OUT/(STEM+'.pptx'),'w',ZIP_DEFLATED) as z:
    for name,content in data.items():z.writestr(name,content)
texts={str(n):[t.text for t in ET.fromstring(data[f'ppt/slides/slide{n}.xml']).findall('.//a:t',NS) if t.text] for n in range(1,28)}
(BUILD/'read-deck-text.json').write_text(json.dumps(texts,ensure_ascii=False,indent=2)+'\n')
(BUILD/'read-deck-notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2)+'\n')
(BUILD/'read-deck-titles.json').write_text(json.dumps(titles,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'slides':27,'main':8,'appendices_rewritten':19,'links':links,'model_changed':False},ensure_ascii=False))
